node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Check if any other products list PROD-2028EE as compatible
const others = db.prepare(\"SELECT product_id, name, compatible_with_json FROM products WHERE compatible_with_json LIKE '%PROD-2028EE%'\").all();
console.log('Products that list PROD-2028EE as compatible:', JSON.stringify(others, null, 2));

// Also check if any products share the same subcategory for context
const related = db.prepare(\"SELECT product_id, name, compatible_with_json FROM products WHERE subcategory = 'Mobile Accessories'\").all();
console.log('\nAll Mobile Accessories:', JSON.stringify(related, null, 2));
"

